// src/components/shared/emptyState.js — the one way a view says "nothing here".
//
// R-038. Five views each hand-rolled a text-only .empty div, and the wording was
// the only thing any of them had. The user asked for a glyph and centring; this
// is the single builder, so the next view cannot rebuild the state differently,
// which is the same argument that made panelDialog an API rather than a
// convention.
//
// The HINT line is optional and short. It exists for the one case where the
// empty state must teach (Remover: what does arming do), not as a place to
// reprint documentation; if a hint runs past a sentence it belongs elsewhere.

/**
 * @param {string} icon  an entry from Icons (an SVG string from our own set;
 *                       never page-derived markup, which is why innerHTML here
 *                       is safe and stays safe)
 * @param {string} text  the short line, e.g. "No notes yet"
 * @param {string} [hint] one optional quieter sentence under it
 * @returns {HTMLDivElement} a ready .empty element
 */
export function emptyState(icon, text, hint) {
  const box = document.createElement('div');
  box.className = 'empty';

  const glyph = document.createElement('span');
  glyph.className = 'empty-icon';
  glyph.innerHTML = icon || '';
  box.appendChild(glyph);

  const line = document.createElement('span');
  line.textContent = text;
  box.appendChild(line);

  if (hint) {
    const sub = document.createElement('span');
    sub.className = 'empty-hint';
    sub.textContent = hint;
    box.appendChild(sub);
  }
  return box;
}

/** Fill a STATIC empty host (Remover's, which also toggles hidden) with the
 *  same content the builder produces, so the two paths cannot drift. */
export function fillEmptyState(host, icon, text, hint) {
  const built = emptyState(icon, text, hint);
  host.replaceChildren(...built.childNodes);
}
