/* noteEditor.js — the editing session behind an open note.
 *
 * WHY THIS IS NOT IN sidepanel.js. Autosave turns note editing from one event
 * (the Save click) into a small state machine: a debounce, an id that is minted
 * mid-session, a write order that must not race, and a revert that has to undo
 * writes that already happened. None of that needs the DOM, and all of it needs
 * testing, so it lives here and sidepanel.js only wires inputs to it.
 *
 * WHAT CANCEL MEANS NOW, which is the whole design. Before autosave, Cancel
 * worked by doing nothing: no write had happened, so closing discarded the edit.
 * That is gone. Cancel is now a REVERT, and it undoes more than it used to: it
 * restores the note to whatever it said when the editor OPENED, not merely since
 * the last keystroke. A note that never existed before this session is deleted
 * instead, because there is no earlier text to go back to.
 *
 * WHY THE ID IS KEPT AFTER AN EMPTY-OUT. "An empty note is a cancelled note" is
 * an older rule and it survives: clearing both fields deletes the record. But the
 * session HOLDS ON to the id, so typing again puts the note back under the same
 * key rather than minting a second one. Without that, emptying and retyping an
 * existing note would silently replace it with a stranger that happens to read
 * the same, and Cancel would have nothing to restore it onto.
 *
 * WRITES ARE SERIALISED, not fired in parallel. Every operation is appended to
 * one promise chain, so a revert cannot land before the autosave it is meant to
 * undo. This is the reason revert() is safe to call while a write is in flight.
 */

/* Long enough that a phrase writes once instead of once per space, short enough
   that closing the panel mid-sentence loses nothing a person would notice. */
export const AUTOSAVE_DELAY = 600;

export function createNoteSession(db, opts = {}) {
  const delay = opts.delay === undefined ? AUTOSAVE_DELAY : opts.delay;
  const setTimer = opts.setTimeout || ((fn, ms) => setTimeout(fn, ms));
  const clearTimer = opts.clearTimeout || ((t) => clearTimeout(t));

  let active = null;
  let pending = { title: '', body: '' };
  let timer = null;
  let chain = Promise.resolve();

  function cancelTimer() {
    if (timer !== null) { clearTimer(timer); timer = null; }
  }

  function open(note) {
    cancelTimer();
    const existing = note && note.id ? note : null;
    active = {
      id: existing ? existing.id : null,
      /* The baseline carries the ORIGINAL id, so reverting an emptied-out note
         restores the same record rather than a copy of its text. */
      baseline: existing
        ? { id: existing.id, title: existing.title || '', body: existing.body || '' }
        : null,
      dead: false,
    };
    pending = {
      title: active.baseline ? active.baseline.title : '',
      body: active.baseline ? active.baseline.body : '',
    };
    return active;
  }

  function change(title, body) {
    if (!active) return;
    pending = { title, body };
    cancelTimer();
    timer = setTimer(() => { timer = null; flush(); }, delay);
  }

  function flush() {
    cancelTimer();
    if (!active) return chain;
    const session = active;
    const { title, body } = pending;

    chain = chain.then(async () => {
      /* Reverted while this was queued. Writing now would resurrect exactly what
         the user asked to throw away. */
      if (session.dead) return;

      if (!title.trim() && !body.trim()) {
        if (session.id) await db.deleteNote(session.id);
        return;
      }

      const rec = await db.saveNote({ id: session.id, title, body });
      session.id = rec.id;
    });
    return chain;
  }

  /* Save, and the back arrow. Both mean "I am finished": the text is already in
     the database, so this only lands a pending debounce and closes. */
  function commit() {
    const done = flush();
    active = null;
    return done;
  }

  function revert() {
    cancelTimer();
    const session = active;
    active = null;
    if (!session) return chain;
    session.dead = true;

    chain = chain.then(async () => {
      if (session.baseline) {
        /* updatedAt moves to now even though the text is the original. The note
           WAS touched, and preserving the old stamp would mean widening
           saveNote's contract to accept a timestamp for one caller's tidiness. */
        await db.saveNote(session.baseline);
      } else if (session.id) {
        await db.deleteNote(session.id);
      }
    });
    return chain;
  }

  return {
    open,
    change,
    flush,
    commit,
    revert,
    get id() { return active ? active.id : null; },
    get isOpen() { return active !== null; },
    settled: () => chain,
  };
}
