// src/services/removerRules.js — how a stored remover rule presents itself.
//
// Pure, because the one interesting decision here burned us rendered-side: a
// stored selector is a PATH (id, then every ancestor, then the element that was
// actually removed), and truncating a path from the left eats the only part
// that differs. Four rules on one feed item all opened with the same #id and
// read as one rule four times. The DISPLAY NAME is therefore the LAST segment:
// the thing that was removed, which is both the shortest and the most
// meaningful part. Derived at render, never stored; the full selector stays in
// storage, in tooltips and in matching untouched.

/** One rule, normalised. Rules predating the flags are plain strings. */
export function readRule(rule) {
  return {
    selector: typeof rule === 'string' ? rule : ((rule && rule.selector) || ''),
    specific: typeof rule === 'object' && rule !== null && !!rule.specific,
    broad: typeof rule === 'object' && rule !== null && !!rule.broad,
  };
}

/**
 * The rule's display name: the segment after the last combinator.
 *
 * Split on `>` because that is the only combinator the selector engine emits
 * (see selectorEngine.js: id, or a chain of `parent > child` steps). A page
 * could not have injected a `>` inside the parts we store, since class names
 * and ids cannot contain it. Descendant-space selectors never occur in our own
 * output, so they fall through whole, which is the right failure: showing more
 * than the target beats showing the wrong piece of it.
 */
export function ruleName(selector) {
  const s = String(selector || '').trim();
  if (!s) return '';
  const parts = s.split('>');
  return (parts[parts.length - 1] || '').trim() || s;
}

/** The rule's state IN WORDS. This line replaces two unlabelled checkboxes and
 *  a corner legend reading S=Specific B=Broad. */
export function ruleLabel(r) {
  const scope = r.specific ? 'This page only' : 'Whole site';
  return r.broad ? `${scope} · broad match` : scope;
}
